  intent.Set("captureReceiptSha256", base::HexEncodeLower(Digest(transfer_->receipt)));
  intent.Set("nativeProfileId", profile_id_); intent.Set("bindingEpoch", binding_);
  intent.Set("restoreEpoch", restoration_);
